export function dayNumber(value){const time=Date.parse(String(value||'').slice(0,10)+'T12:00:00Z');return Number.isFinite(time)?Math.floor(time/86400000):NaN}
export function slotIndex(date,window='morning'){const day=dayNumber(date);return Number.isFinite(day)?day*2+(window==='evening'?1:0):NaN}
export function rentalDays(startDate,returnDate,pickupWindow='morning',returnWindow='evening'){const start=dayNumber(startDate),finish=dayNumber(returnDate);if(!Number.isFinite(start)||!Number.isFinite(finish)||finish<start)return 0;const calendarDays=finish-start,pickupOrder=pickupWindow==='evening'?1:0,returnOrder=returnWindow==='evening'?1:0;return calendarDays===0?(returnOrder>pickupOrder?1:0):calendarDays+(returnOrder>pickupOrder?1:0)}
export function isWeekendTariffMoment(date,window='morning'){const time=Date.parse(String(date||'').slice(0,10)+'T12:00:00Z');if(!Number.isFinite(time))return false;const day=new Date(time).getUTCDay();return day===6||(day===5&&window==='evening')||(day===0&&window==='morning')}
export function paidDayMoments(startDate,returnDate,pickupWindow='morning',returnWindow='evening'){const count=rentalDays(startDate,returnDate,pickupWindow,returnWindow),start=dayNumber(startDate);if(!count||!Number.isFinite(start))return[];return Array.from({length:count},(_,index)=>{const d=new Date((start+index)*86400000+12*3600000).toISOString().slice(0,10);return{date:d,window:pickupWindow,weekend:isWeekendTariffMoment(d,pickupWindow)}})}
export function isWeekendDeposit(startDate,returnDate,pickupWindow='morning',returnWindow='evening'){const moments=paidDayMoments(startDate,returnDate,pickupWindow,returnWindow);return moments.length>=2&&moments.some(item=>item.weekend)}
export function rentalBase(product,startDate,returnDate,pickupWindow='morning',returnWindow='evening'){if(!product)return 0;const moments=paidDayMoments(startDate,returnDate,pickupWindow,returnWindow);if(!moments.length)return 0;if(moments.length===2&&moments.every(item=>item.weekend)&&Number(product.saturdaySunday)>0)return Number(product.saturdaySunday);return moments.reduce((sum,item)=>sum+(Number(item.weekend?product.weekend:product.weekday)||0),0)}
export function periodsOverlap(aStartDate,aReturnDate,aPickupWindow='morning',aReturnWindow='evening',bStartDate,bReturnDate,bPickupWindow='morning',bReturnWindow='evening'){const a0=slotIndex(aStartDate,aPickupWindow),a1=slotIndex(aReturnDate,aReturnWindow),b0=slotIndex(bStartDate,bPickupWindow),b1=slotIndex(bReturnDate,bReturnWindow);if(![a0,a1,b0,b1].every(Number.isFinite))return false;return a0<b1&&a1>b0}
